// No network, storage, analytics or shared private-note state.
for(const button of document.querySelectorAll('[data-enable]'))button.disabled=false;
const text={en:{choose:'Choose a response first.',matches:'This matches the bounded guide.',reconsider:'Reconsider using the guide below.',download:'Downloaded notes; nothing was uploaded.'},es:{choose:'Primero elige una respuesta.',matches:'La respuesta coincide con la guía delimitada.',reconsider:'Reconsidera tu respuesta con la guía siguiente.',download:'Notas descargadas; no se ha enviado nada.'}};
for(const form of document.querySelectorAll('[data-study-task]')) form.addEventListener('submit',event=>{event.preventDefault();const choice=new FormData(form).get('choice'),l=text[form.dataset.language];form.querySelector('[data-result]').textContent=!choice?l.choose:choice===form.dataset.answer?l.matches:l.reconsider;});
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
for(const button of document.querySelectorAll('[data-export-study]'))button.addEventListener('click',()=>{const {exportStudy:id,revision,language}=button.dataset;download(`${id}-${revision}-${language}-notes.json`,{schemaVersion:1,id,revision,language,notes:document.querySelector('#study-notes').value,scope:'User notes; no assessed outcome or observed mastery.'});document.querySelector('[data-export-status]').textContent=text[language].download;});
const search=document.querySelector('[data-catalog-search]'),provider=document.querySelector('[data-catalog-provider]');
function filter(){const q=search.value.trim().toLocaleLowerCase('en'),p=provider.value;let shown=0;for(const card of document.querySelectorAll('[data-provider]')){const visible=(!p||card.dataset.provider===p)&&card.textContent.toLocaleLowerCase('en').includes(q);card.hidden=!visible;if(visible)shown++;}document.querySelector('[data-catalog-count]').textContent=shown+' records shown';}
search?.addEventListener('input',filter);provider?.addEventListener('change',filter);
document.querySelector('[data-practice-form]')?.addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget),data={schemaVersion:1,kind:'self-recorded-practice',activity:form.get('activity'),observation:form.get('observation'),interpretation:form.get('interpretation'),nextAttempt:form.get('nextAttempt'),scope:'User-entered notes; no independent observation, consent, certification or outcome is inferred.'};download('atlas-practice-notes.json',data);document.querySelector('[data-practice-result]').textContent='Downloaded your notes. No data was uploaded or automatically saved.';});
